const SPRITE_FALLBACK = SPRITES.goblin;

// <img> со спрайтом существа; незнакомый ключ получает запасной спрайт, а не пустоту.
function spriteImg(key) {
  const src = SPRITES[key] || SPRITE_FALLBACK;
  return "<img class='sprite-img' src='" + src + "' alt=''>";
}

// Нарисована ли иконка пикселями (спрайт существа или тайл подземелья), а не
// SVG. Пиксель-арт масштабируется только целыми шагами, SVG — как угодно.
function mapIconIsPixel(key) {
  if (SPRITES[key]) return true;
  return typeof terrainIcon === "function" && !!terrainIcon(key);
}

// Иконка для карты подземелья: у героя, врагов и торговца — спрайт существа,
// у лестниц, ловушек и сундука — тайл подземелья, у меток (прицел
// дальнобойного) — SVG-иконка.
function mapIcon(key) {
  if (SPRITES[key]) return spriteImg(key);
  // Значки состояний врага (state_calm, state_alert, state_search) — свои
  // пиксельные картинки, но не спрайты существ: mapIconIsPixel их не
  // считает, иначе .ent-px растянул бы значок на всю клетку.
  if (typeof STATE_ICONS !== "undefined" && STATE_ICONS[key]) {
    return "<img class='sprite-img' src='" + STATE_ICONS[key] + "' alt=''>";
  }
  if (typeof terrainIcon === "function") {
    const tile = terrainIcon(key);
    if (tile) return "<img class='sprite-img' src='" + tile + "' alt=''>";
  }
  return iconSvg(key);
}

// Картинка предмета для сумки, лавки и кузницы. Раньше все вещи одного слота
// рисовались одной SVG-формой и различались только цветом редкости: меч,
// кинжал и трезубец выглядели одинаково. Вещь без картинки получает прежнюю
// иконку слота.
function itemPic(item, color) {
  const src = item && ITEM_SPRITES[item.id];
  if (src) return "<span class='item-ico item-ico-px'><img class='item-px' src='" + src + "' alt=''></span>";
  return "<span class='item-ico'>" + itemIcon(item ? item.slot : "", color) + "</span>";
}
